import pandas as pd
import numpy as np

# Load data
gas = pd.read_csv("chunks_csv/outlierr/2022_gas.csv")
adj_df = pd.read_csv("chunks_csv/borough_adjacency.csv")

# Build adjacency dictionary
boroughs = set(gas['borough'])
adj = {b: set() for b in boroughs}
for _, row in adj_df.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b in boroughs and n in boroughs:
        adj[b].add(n)
        adj[n].add(b)
gas['neighbors'] = gas['borough'].map(adj)

# Initialize included mask
included = np.ones(len(gas), dtype=bool)
kingston_borough = "Kingston upon Thames"

# Iterative outlier removal
max_iter = 10
for _ in range(max_iter):
    gas['included'] = included
    current_gas_dict = {}
    for idx, row in gas.iterrows():
        if included[idx]:
            current_gas_dict[row['borough']] = row['Gas_value']

    def compute_avg(row):
        if not row['included']:
            return np.nan
        neighbor_vals = []
        for n in row['neighbors']:
            if n in current_gas_dict:
                neighbor_vals.append(current_gas_dict[n])
        if neighbor_vals:
            return np.mean(neighbor_vals)
        return np.nan

    gas['neighborhood_avg'] = gas.apply(compute_avg, axis=1)
    temp = gas[included].dropna(subset=['neighborhood_avg'])
    if len(temp) < 2:
        break

    X = temp['neighborhood_avg'].values
    y = temp['Gas_value'].values
    X_mat = np.column_stack((X, np.ones(len(X))))
    try:
        beta = np.linalg.lstsq(X_mat, y, rcond=None)[0]
    except np.linalg.LinAlgError:
        break
    temp['predicted'] = beta[0] * X + beta[1]
    temp['residual'] = temp['Gas_value'] - temp['predicted']

    non_kingston = temp['borough'] != kingston_borough
    candidate = temp[non_kingston]
    if candidate.empty:
        break

    max_idx = candidate['residual'].abs().idxmax()
    max_residual = candidate.loc[max_idx, 'residual']
    std_res = temp['residual'].std()
    if std_res == 0:
        break

    if abs(max_residual) > 2.5 * std_res:
        included[max_idx] = False
    else:
        break

# Final assessment
gas['included'] = included
current_gas_dict_final = {}
for idx, row in gas.iterrows():
    if included[idx]:
        current_gas_dict_final[row['borough']] = row['Gas_value']

gas['neighborhood_avg_final'] = gas.apply(compute_avg, axis=1)
gas_final = gas[included].copy()
temp_final = gas_final.dropna(subset=['neighborhood_avg_final'])

if len(temp_final) >= 2:
    X_final = temp_final['neighborhood_avg_final'].values
    y_final = temp_final['Gas_value'].values
    X_mat_final = np.column_stack((X_final, np.ones(len(X_final))))
    try:
        beta_final = np.linalg.lstsq(X_mat_final, y_final, rcond=None)[0]
    except np.linalg.LinAlgError:
        beta_final = [0, 0]
    temp_final['predicted'] = beta_final[0] * X_final + beta_final[1]
    temp_final['residual'] = temp_final['Gas_value'] - temp_final['predicted']

    king_row = temp_final[temp_final['borough'] == kingston_borough]
    if not king_row.empty:
        residual_king = king_row['residual'].iloc[0]
        temp_final_no_king = temp_final[temp_final['borough'] != kingston_borough]
        if len(temp_final_no_king) > 0:
            std_res_final = temp_final_no_king['residual'].std()
            if std_res_final == 0:
                z_kingston = residual_king
            else:
                z_kingston = residual_king / std_res_final
        else:
            z_kingston = residual_king
    else:
        z_kingston = 0.0
else:
    z_kingston = 0.0

# Classify outlier status
if z_kingston > 2.5:
    verdict = "OUTLIER - HIGH"
elif z_kingston < -2.5:
    verdict = "OUTLIER - LOW"
else:
    verdict = "NOT AN OUTLIER"

data_points_used = len(temp_final)
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {verdict} (z = {z_kingston})")
